server {
    listen 80;
    server_name localhost;

    # Cache configuration for API endpoints
    # Shared cache zone named 'apicache' with 10m size
    # Cache duration: 1000 seconds (minimum)
    # Headers: X-Cache-Status showing HIT/MISS

    # Proxy location for API service endpoints
    location /api/service1 {
        proxy_pass http://localhost:3000/data;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        # Enable caching for 1000 seconds
        proxy_cache apicache;
        proxy_cache_valid 200 1000s;

        # Return X-Cache-Status header
        add_header X-Cache-Status $upstream_cache_status always;
    }

    location /api/service2 {
        proxy_pass http://localhost:3001/data;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        proxy_cache apicache;
        proxy_cache_valid 200 1000s;

        add_header X-Cache-Status $upstream_cache_status always;
    }

    location /api/service3 {
        proxy_pass http://localhost:3002/data;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        proxy_cache apicache;
        proxy_cache_valid 200 1000s;

        add_header X-Cache-Status $upstream_cache_status always;
    }

    location /api/service4 {
        proxy_pass http://localhost:3003/data;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        proxy_cache apicache;
        proxy_cache_valid 200 1000s;

        add_header X-Cache-Status $upstream_cache_status always;
    }

    # Redirect routes - 302 status
    location /sunny {
        location = /api/service1;
        rewrite ^/sunny/(.*)$ /$1 permanent;
        # Actually need to redirect to /api/service1 with 302
        return 302 /api/service1;
    }

    location /woods {
        location = /api/service2;
        rewrite ^/woods/(.*)$ /$1 permanent;
        return 302 /api/service2;
    }

    location /stream {
        location = /api/service3;
        rewrite ^/stream/(.*)$ /$1 permanent;
        return 302 /api/service3;
    }

    # Main data endpoints (direct access)
    location /data {
        # These should be accessible directly from servers
        return 200 "Sun is yellow"; # For server1
    }
}
EOF
